function applyStyle() {
    // Your CSS as text 
    var styles = `
        .work_efforts_container {
            & .work-efforts-table .datatable {
                margin-top: 1rem;
            }
            & {
                max-width: 100% !important;;
            }
            & .work-efforts-controls {
                display: inline-flex;
                width: 100%;
            }
            & .work-efforts-controls .frappe-control {
                flex: 0 1 150px;
            }
            & .work-efforts-group-header {
                display: flex; 
                justify-content: space-around;
            }
            & .work-efforts-group-header > span {
                width: 33.33%;
                font-size: 10px;
                display: flex;
                justify-content: center;
            }
            & .work-efforts-group {
                display: flex;
                flex-direction: row;
                flex-wrap: nowrap;
                justify-content: space-around;
            }
            & .work-efforts-table .datatable .dt-row.dt-row-header, 
            & .work-efforts-table .datatable .dt-cell.dt-cell--header {
                height: auto;
                text-align: center;
                display: flex;
            }
            & .work-efforts-table .dt-cell {
                /**border: 1px solid #d1d8dd;
                position: static;**/
            }
            & .work-efforts-table .datatable .dt-cell--focus .dt-cell__content {
                border-color: var(--gray-200);
            }
            & .work-efforts-table div[data-indent="1"] .dt-tree-node {
                padding-left: 40px!important;
            }
            & .work-efforts-table div[data-indent="2"] .dt-tree-node {
                padding-left: 80px!important;
            }
            & .work-efforts-table div[data-indent="3"] .dt-tree-node {
                padding-left: 120px!important;
            }
            & .work-efforts-table .datatable .dt-scrollable {
                max-height: max(calc(100vh - 400px),350px);
            }
            & .work-efforts-table .datatable .dt-fit-height {
                height: fit-content !important;
                min-height: auto !important;
            }
            & .work-efforts-table .datatable .dt-header .dt-cell--header .dt-cell__content {
                font-weight: 600;    
                margin: auto;
            }
            & .work-efforts-group > div {
                min-width: 3em;
                text-align: center;
            }
            & .we-group-actual:not(.zero):has(.readonly-fact) {
                cursor: pointer;
            }
            & .work-efforts-group > div.zero {
                color: var(--bg-dark-gray);
            }
            & .editable-forecast {
                cursor: text;
                isplay: block;
            }
            & .we-edit-input {
                text-align: center;
                width: 4em;
                outline: none;
                background-color: transparent;
                border: 0px;
            }
            & .we-edit-input.error {
                background-color: var(--error-border);
            }
            & .delete-role-btn {
                padding: 0px!important;
                border-radius: 50%;
                box-sizing: border-box;
                line-height: 0;
                margin-left: 0.5rem;
             }
            & .dt-cell__content {
                font-feature-settings: "tnum";
                width: 180px;
                padding: 2px;
            }
            & .dt-cell__content--col-0 {
                text-align: center;
            }
            & .dt-cell__content--col-0 input[type=checkbox] {
                margin: auto !important;
            }
            & .dt-cell__content--col-1 {
                color: var(--text-light);
                font-weight: 200;
                font-size: var(--text-md);
            }
            
            /*Высота ячеек*/
            & .work-efforts-table .datatable .dt-row, 
            & .work-efforts-table .dt-cell__content,
            & .work-efforts-table .dt-cell {
                height: auto !important;
            }
            & .work-efforts-table .vrow {
                position: static!important;
                width: fit-content;
            }
            & .new-role-select, 
            & .new-role-select option {
                width: 100%;
            }
        }
    `;

    var styleSheet = document.createElement("style");
    styleSheet.textContent = styles;
    document.head.appendChild(styleSheet);
}

applyStyle();

// Клиентский скрипт для Doctype "Project"
frappe.ui.form.on("Project", {
    refresh: function(frm) {
        console.log("refresh");
        render_work_efforts_table(frm);
    }
});

/**
 * Отрисовка таблицы «Трудозатраты»
 */
function render_work_efforts_table(frm) {
    if ( frm.last_loaded_project == frm.doc.name && ( new Date() - frm.last_loaded_time ) < 300000 ) {
        console.log("Загружены данные проекта и прошло менее 5 минут..");
        return;
    }

    let wrapper = frm.get_field("custom_work_efforts").$wrapper;
    wrapper.addClass("work_efforts_container");

    wrapper.empty();
    frm.aggregatedTasks = null;

    let controls = $('<div class="work-efforts-controls"></div>').appendTo(wrapper);
    let table_container = $('<div class="work-efforts-table"></div>').appendTo(wrapper);

    controls.append(`
        <button class="btn btn-default" id="we_save_plan">${__('Сохранить план')}</button>
        <button class="btn btn-default" id="toggle_plan">${__("Показать план")}</button>
        <button class="btn btn-default" id="toggle_delta">${__("Показать Δ")}</button>
    `);
    
    addViewOptionsControl(frm, controls);
    let selectedPeriodType = "month";
    let selectedUnit = "hours";
    
    frm.hide_plan = frm.hide_plan || true;
    frm.hide_delta = frm.hide_delta || true;

    controls.find('#we_save_plan').on('click', function() {
        if ( !frm.work_efforts_dt.rowmanager.getCheckedRows()?.length ) {
            frappe.msgprint(__("Выберите задачи, для которых необходимо сохранить плановые данные."));
        } else {
            frappe.confirm(
                __("Вы уверены, что хотите сохранить выбранные прогнозные / фактические данные как плановые?"),
                () => {
                    save_forecast_as_plan(frm);
                },
                () => {
                    frappe.show_alert(__("Операция отменена"), 3);
                }
            );
        }
    });
    
    controls.find('#toggle_plan').on('click', function() {
        frm.hide_plan = !frm.hide_plan;
        $(this).text(frm.hide_plan ? __("Показать план") : __("Скрыть план"));
        updateTable(frm, selectedPeriodType, selectedUnit);
        render_work_efforts_chart(frm);
    });
    
    controls.find('#toggle_delta').on('click', function() {
        frm.hide_delta = !frm.hide_delta;
        $(this).text(frm.hide_delta ? __("Показать Δ") : __("Скрыть Δ"));
        updateTable(frm, selectedPeriodType, selectedUnit);
    });

    function init_table() {
        let columns = get_columns_definition(frm, selectedPeriodType, selectedUnit);

        DataTable.instances = 99;
        frm.work_efforts_dt = new StickyDataTable(table_container[0], {
        //frm.work_efforts_dt = new DataTable(table_container[0], {
            stickyColumnsCount: 4,
            columns: columns,
            data: [],
            inlineFilters: false,
            layout: "fixed",
            logs: true,
            disableReorderColumn: true,
            serialNoColumn: true,
            checkboxColumn: true,
            checkedRowStatus: true,
            dynamicRowHeight: true,
            showTotalRow: true,
            cellHeight: null,
            treeView: true,
            freezeMessage: __("Идет загрузка данных.."),
            
            hooks: {
                columnTotal(columnValues, cell) {
                    if (cell.column.id == "total") {
                        let aggregatedTasks = cur_frm.aggregatedTasks || {};
                        let periods = get_display_periods(cur_frm, cur_frm.currentPeriodType || "month");
                
                        let total_plan = 0;
                        let total_actual = 0;
                        
                        // Вспомогательная рекурсивная функция: возвращает { plan, actual } для заданной задачи и роли за период
                        function sumForTaskByPeriod(taskId, period, planRoles, actualRoles) {
                            let task = aggregatedTasks[taskId];
                            if (!task) return { plan: 0, actual: 0 };
                    
                            // если роль задана — ищем только её запись; иначе — суммируем по всем ролям
                            let plan = 0, actual = 0;
                            let e = (task.role_data || []);
                            
                            if ( e && e.length ) {
                                e.forEach(r => {
                                    const planIndex = planRoles.indexOf(r.role);
                                    const actualIndex = actualRoles.indexOf(r.role);
                                    
                                    if (planIndex > -1) {
                                        let curr_plan = parseFloat(r[`plan_${period.year}_${period.month}`]) || 0;
                                        
                                        if ( curr_plan ) {
                                            plan += curr_plan;
                                            planRoles.splice(planIndex, 1);
                                        }
                                    }
                                    
                                    if (actualIndex > -1) {
                                        let curr_actual = 0;
                                        
                                        if (period.is_past) {
                                            curr_actual = parseFloat(r[`fact_${period.year}_${period.month}`]) || 0;
                                        } else {
                                            curr_actual = parseFloat(r[`forecast_${period.year}_${period.month}`]) || 0;
                                        }
                                        
                                        if ( curr_actual ) {
                                            actual += curr_actual;
                                            actualRoles.splice(actualIndex, 1);
                                        }
                                    }
                                });
                            }
                    
                            // Если явных данных нет — рекурсивно суммируем детей
                            let childTasks = Object.values(aggregatedTasks).filter(t => t.parent_task === taskId);
                            childTasks.forEach(child => {
                                let childPlanRoles = [...planRoles];
                                let childActualRoles = [...actualRoles];
                                if ( !planRoles.length && !actualRoles.length ) return;
                                let r = sumForTaskByPeriod(child.value, period, childPlanRoles, childActualRoles);
                                plan += r.plan;
                                actual += r.actual;
                            });
                            return { plan: plan, actual: actual};
                        }
                    
                        // Для каждого периода суммируем по всем корням
                        let plan_per_period = [];
                        let actual_per_period = [];
                        
                        let all_roles = get_project_roles(frm).filter(r => r );
                        let rootTasks = Object.values(aggregatedTasks).filter(t => !t.parent_task);
                    
                        if ( rootTasks.length ) {
                            periods.forEach(period => {
                                let total_period_plan = 0;
                                let total_period_actual = 0;
                                rootTasks.forEach(root => {
                                    let planRoles = [...all_roles];
                                    let actualRoles = [...all_roles];
                                    //if ( !planRoles.length && !actualRoles.length ) return;
                                    let res = sumForTaskByPeriod(root.value, period, planRoles, actualRoles);
                                    total_period_plan += res.plan;
                                    total_period_actual += res.actual;
                                });
                                total_plan += total_period_plan;
                                total_actual += total_period_actual;
                            });
                        }
                        
                        let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                        
                        return `<div class="work-efforts-group">
                            ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                            <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                            ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat(delta).toFixed(1)}%</span></div>`}
                          </div>`;
                          
                    } else if ( cell.colIndex == 0 ) {
                        return __('Итого');
                    } else if ( cell.colIndex > 1 ) {
                        let parts = cell.column.id.split("_");
                        
                        if(parts.length == 3) {
                            let year = parts[1];
                            let month = parts[2];
                            let periods = get_display_periods(cur_frm, cur_frm.currentPeriodType || "month");
                            let aggregatedTasks = cur_frm.aggregatedTasks || {};
                        
                            let total_plan = 0;
                            let total_actual = 0;
                            
                            // Функция для рекурсивного подсчета данных за конкретный месяц
                            function calculateRoleDataMonthly(role, taskId, year, month, visited = new Set()) {
                                if (visited.has(taskId)) return { plan: 0, actual: 0 };
                                visited.add(taskId);
                                
                                let task = aggregatedTasks[taskId];
                                if (!task) return { plan: 0, actual: 0 };
                                
                                let roleEntry = task.role_data.find(r => r.role === role);
                                
                                // Считаем данные самой задачи для данной роли
                                let taskPlan = 0;
                                let taskActual = 0;
                                
                                if (roleEntry) {
                                    let planKey = `plan_${year}_${month}`;
                                    let forecastKey = `forecast_${year}_${month}`;
                                    let factKey = `fact_${year}_${month}`;
                                    
                                    taskPlan = parseFloat(roleEntry[planKey]) || 0;
                                    let period = periods.find(p => p.year == year && p.month == month);
                                    if (period.is_past) {
                                        taskActual = parseFloat(roleEntry[factKey]) || 0;
                                    } else {
                                        taskActual = parseFloat(roleEntry[forecastKey]) || 0;
                                    }
                                }
                                
                                // КРИТИЧЕСКОЕ ПРАВИЛО: Если у задачи есть данные для этой роли - используем ТОЛЬКО их
                                if (taskPlan > 0 || taskActual > 0) {
                                    return {
                                        plan: taskPlan,
                                        actual: taskActual
                                    };
                                }
                                
                                // Если у задачи нет данных для этой роли - суммируем данные дочерних задач
                                let childTasks = Object.values(aggregatedTasks).filter(t => t.parent_task === taskId);
                                let childrenData = { plan: 0, actual: 0 };
                                
                                childTasks.forEach(childTask => {
                                    let childData = calculateRoleDataMonthly(role, childTask.value, year, month, visited);
                                    childrenData.plan += childData.plan;
                                    childrenData.actual += childData.actual;
                                });
                                
                                return childrenData;
                            }
                            
                            // Для каждой роли находим корневые задачи и считаем данные
                            let allRoles = new Set();
                            Object.values(aggregatedTasks).forEach(task => {
                                task.role_data.forEach(roleEntry => {
                                    if (roleEntry.role) allRoles.add(roleEntry.role);
                                });
                            });
                            
                            allRoles.forEach(role => {
                                // ИСПРАВЛЕНИЕ: Используем тот же подход, что и в calculateRoleData
                                // Находим ВСЕ корневые задачи (без parent_task)
                                let rootTasks = Object.values(aggregatedTasks).filter(task => 
                                    !task.parent_task
                                );
                                
                                // Для каждой корневой задачи считаем данные для текущей роли
                                rootTasks.forEach(rootTask => {
                                    let data = calculateRoleDataMonthly(role, rootTask.value, year, month);
                                    total_plan += data.plan;
                                    total_actual += data.actual;
                                });
                            });
                        
                            let delta = total_plan ? (((total_actual - total_plan) / total_plan) * 100).toFixed(1)  : 0;
                            
                            return `<div class="work-efforts-group"
                                data-year="${year}" 
                                data-month="${month}">
                                ${cur_frm.hide_plan ? "" : `<div class="we-group-plan"><span>${total_plan.toFixed(1)}</span></div>`}
                                <div class="we-group-actual"><span class="readonly-fact">${total_actual.toFixed(1)}</span></div>
                                ${cur_frm.hide_delta ? "" : `<div class="we-group-delta"><span>${Number.parseFloat( delta ).toFixed(1)}%</span></div>`}
                              </div>`;
                        }
                    }
                    return "";
                }
            }
        });

        load_work_efforts_data(frm, selectedPeriodType, selectedUnit);
    }
    init_table();
    frm.last_loaded_project = frm.doc.name;
    frm.last_loaded_time = new Date();
}


function addViewOptionsControl(frm, controls) {
    frm.view_options = frm.view_options || __("Прогноз и факт");
    const control = frappe.ui.form.make_control({
		parent: controls,
		df: {
			fieldtype: 'Select',
			fieldname: "view-options",
			options: [
                __("Прогноз и факт"),
                __("Только прогноз"),
                __("Только факт"),
            ],
			get_status: function(i) {
                return "Write";
            },
            change: async function(i){
                if ( this.value != this.last_value ) {
                    frm.view_options = this.value;
                    updateTable( frm, "month", "hours" );
                    render_work_efforts_chart(frm);
                }
            }
		},
		value: frm.view_options,
		only_input: true,
        render_input: true
	});
}

function get_project_roles(frm) {
    let roles = [];
    if (frm.doc.custom_ts_details) {
        roles = frm.doc.custom_ts_details.map((x) => x.pt_role );
    }
    roles.push("");
    return Array.from( new Set(roles));
}

function get_display_periods(frm, periodType) {
    let periods = [];
    let month_start = frappe.datetime.month_start();
    let start_date = frm.doc.expected_start_date ? frm.doc.expected_start_date : month_start;
    let start = frappe.datetime.str_to_obj(start_date);
    let end_date = frm.doc.expected_end_date ? frm.doc.expected_end_date : frappe.datetime.add_months(start, 12);
    let end = frappe.datetime.str_to_obj(end_date);

    if (periodType === "month") {
        let current = start;
        while (frappe.datetime.obj_to_str(current) <= frappe.datetime.obj_to_str(end)) {
            let year = current.getFullYear();
            let i = current.getMonth();
            let is_past = ( frm.view_options == __("Прогноз и факт") ) 
                ? frappe.datetime.obj_to_str(current) < month_start
                : ( frm.view_options == __("Только факт") );
            periods.push({ year: year, month: i + 1, is_past: is_past });
            current = frappe.datetime.str_to_obj( frappe.datetime.add_months(current, 1) );
        }
    }
    return periods;
}

function updateTable(frm, periodType, unit) {
    let visibleRows =  frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
    
    frm.work_efforts_dt.refresh(
        Object.values(frm.aggregatedTasks),
        get_columns_definition(frm, periodType, unit)
    );
    
    frm.work_efforts_dt.rowmanager.collapseAllNodes();
    frm.work_efforts_dt.rowmanager.showRows(visibleRows);
    cur_frm.work_efforts_dt.bodyScrollable.dispatchEvent(new CustomEvent('scroll'));
}

/**
 * Загрузка данных для таблицы «Трудозатраты»
 *
 * Здесь необходимо объединить данные:
 * – иерархии задач (с использованием whitelisted‑метода custom_task_get_children),
 * – данных из DocType "Project Work Efforts" (плановые и прогнозные данные),
 * – фактических данных из "User Timesheet Position".
 */
function load_work_efforts_data(frm, periodType, unit, updateRows) {
    // Массив для итоговых данных таблицы
    let table_data = [];
    let aggregatedTasks = {};

    // Получаем иерархию задач проекта через вызов метода custom_task_get_children.
    // Для начального уровня parent – пустая строка.
    frappe.call({
        method: "custom_task_get_children",
        args: {
            project: frm.doc.name,
            is_root: true,
            is_all: true
        },
        callback: function(r) {
            if (r.message) {
                // r.message – массив объектов с полями: value, title, expandable, parent_task, type, status.
                let tasks = r.message;
                let results = [];
                let parents = [];

                let addResults = function(results, parents, tasks, curNode) {
                    let parent = curNode.parent_task || "";

                    if ( !parents.includes( parent ) ) {
                        parents.push( parent );
                        let parentNode = tasks.filter((node) => ( node.value == parent ) )[0];

                        if (parentNode) {
                            addResults( results, parents, tasks, parentNode );
                        }

                        if (parentNode || !parent) {
                            let parentData = tasks.filter((node) => ( ( node.parent_task || "" ) == parent && !node.is_milestone ) );
                            results[ ( parent ? parent : "" ) ] = parentData;
                        }
                    }
                };

                for (const node of tasks) {
                    addResults( results, parents, tasks, node );
                }

                
                let periods = get_display_periods(frm, periodType);

                let saveData = function(tasks, level) {
                    if ( tasks ) {
                        tasks.forEach(function(task) {
                            if (!aggregatedTasks[task.value]) {
                                // Создаем базовую запись задачи и инициализируем пустой массив для данных по ролям
                                aggregatedTasks[task.value] = Object.assign({}, task);
                                aggregatedTasks[task.value].indent = level;
                                aggregatedTasks[task.value].role_data = [];
                            } else {
                                // Обновляем уровень indent, если требуется
                                aggregatedTasks[task.value].indent = level;
                            }
    
                            if( results[task.value] ) {
                                saveData(results[ task.value ],level+1);
                            }
                        });
                    }
                };
                
                saveData(results[""], 0);

                // Загружаем реальные данные из Project Work Efforts 
                frappe.db.get_list("Project Work Efforts", {
                    filters: { pwe_project: frm.doc.name },
                    fields: ["name", "pwe_task", "pwe_project_role"],
                    limit: 0
                }).then(pwe_list => {
                    let promises = pwe_list.map(pwe =>
                        frappe.db.get_doc("Project Work Efforts", pwe.name)
                    );
                    return Promise.all(promises);
                }).then(pwe_docs => {
                    
                    pwe_docs.forEach(doc => {
                        let task = doc.pwe_task;
                        let role = doc.pwe_project_role || "";
                        if (aggregatedTasks[task]) {
                            // Ищем запись для данной роли в role_data
                            let roleEntry = aggregatedTasks[task].role_data.find(r => r.role === role);
                            if (!roleEntry) {
                                roleEntry = { role: role };
                                aggregatedTasks[task].role_data.push(roleEntry);
                            }
                            // Для каждого периода из дочерней таблицы заполняем данные
                            if (doc.pwe_amount && doc.pwe_amount.length > 0) {
                                doc.pwe_amount.forEach(line => {
                                    let key = `plan_${line.pwea_year}_${line.pwea_month}`;
                                    let key2 = `forecast_${line.pwea_year}_${line.pwea_month}`;
                                    roleEntry[key] = line.pwea_plan || 0;
                                    roleEntry[key2] = line.pwea_expected || 0;
                                });
                            }
                        }
                    });

                    // Обработка фактических данных из User Timesheet Position 
                    frappe.db.get_list("User Timesheet Position", {
                        filters: {
                            project: frm.doc.name,
                            status: "Согласовано",
                            document_type: "Task"
                        },
                        fields: ["name", "document_name", "project_role", "period", "all_hours"],
                        limit: 0
                    }).then(ts_list => {
                        ts_list.forEach(ts => {
                            let parts = ts.period.split("-");
                            if(parts.length >= 2) {
                                let year = parts[0];
                                let month = parts[1];
                                let role = ts.project_role || "";
                                let task = ts.document_name; // Предполагается, что document_name соответствует task.value
                                
                                if (aggregatedTasks[task]) {
                                    // Ищем запись для данной роли
                                    let roleEntry = aggregatedTasks[task].role_data.find(r => r.role === role);
                                    if (!roleEntry) {
                                        // Если такой записи нет, попробуем обновить запись с пустой ролью, если у неё нет плановых/прогнозных данных
                                        let blankEntry = aggregatedTasks[task].role_data.find(r => !r.role || r.role.trim()==="");
                                        let entryValues = Object.values( blankEntry || [] ).find(r => String(r).trim()!="" && String(r).trim()!=0 );
                                        if (blankEntry && !entryValues) {
                                            blankEntry.role = role;
                                            roleEntry = blankEntry;
                                        } else {
                                            // Иначе создаем новую запись
                                            roleEntry = { role: role };
                                            aggregatedTasks[task].role_data.push(roleEntry);
                                        }
                                    }
                                    // Суммируем фактические часы
                                    let factKey = `fact_${year}_${flt(month)}`;
                                    roleEntry[factKey] = (roleEntry[factKey] || 0) + flt(ts.all_hours);
                                    // Сохраняем UTP name
                                    let factUTPs = `fact_utps_${year}_${flt(month)}`;
                                    if (!roleEntry[factUTPs]) {
                                        roleEntry[factUTPs] = [];
                                    }
                                    roleEntry[factUTPs].push(ts.name);
                                }
                            }
                        });

                        // Удаляем из каждой задачи все записи с пустой ролью
                        Object.values(aggregatedTasks).forEach(task => {
                            task.role_data = (task.role_data || [])
                                .filter(r => r.role && r.role.trim() !== "");
                        });
                        
                        rollup_fact_data(aggregatedTasks);
                        
                        // Преобразуем агрегированные задачи в массив
                        cur_frm.aggregatedTasks = aggregatedTasks;
                        let table_data = Object.values(aggregatedTasks);
                        
                        let visibleRows;
                        if (updateRows) {
                            visibleRows =  frm.work_efforts_dt.bodyRenderer.visibleRowIndices;
                        }
                        
                        frm.work_efforts_dt.refresh(table_data);
                        frm.work_efforts_dt.rowmanager.collapseAllNodes();
                        
                        if ( visibleRows ) {    
                            frm.work_efforts_dt.rowmanager.showRows(visibleRows);
                        }
                    }).catch(err => {
                        frappe.msgprint(__("Ошибка при загрузке данных User Timesheet Position"));
                        console.error(err);
                    }).finally(() => {
                        setCellStyles();
                        render_labour_percentage_chart( frm );
                        render_work_efforts_chart(frm);
                        updateTaskDimension(frm);
                    });
                }).catch(err => {
                    frappe.msgprint(__("Ошибка при загрузке данных Project Work Efforts"));
                    console.error(err);
                });
            }
        }
    });
}

//Функция для "свертывания" (rollup) фактических данных:
//для каждой задачи суммируются фактические трудозатраты (fact_*) из всех дочерних задач с той же ролью.
function rollup_fact_data(aggregatedTasks) {
    // Получаем массив задач, отсортированный по убыванию indent (то есть от самых глубоких к родительским)
    let tasksArray = Object.values(aggregatedTasks).sort((a, b) => b.indent - a.indent);
    tasksArray.forEach(child => {
        if (child.parent_task && aggregatedTasks[child.parent_task]) {
            let parent = aggregatedTasks[child.parent_task];
            // Для каждой записи по роли в дочерней задаче
            child.role_data.forEach(childRoleEntry => {
                let role = childRoleEntry.role;
                // Ищем в родительской задаче запись для той же роли
                let parentRoleEntry = parent.role_data.find(r => r.role === role);
                // Перебираем все свойства, начинающиеся с "fact_"
                for (let prop in childRoleEntry) {
                    if (prop.startsWith("fact_")) {
                        if (!parentRoleEntry) {
                            parentRoleEntry = { role: role };
                            parent.role_data.push(parentRoleEntry);
                        }
                        if (prop.startsWith("fact_utps")) {
                            if ( !parentRoleEntry[prop] ) {
                                parentRoleEntry[prop] = [];
                            }
                            parentRoleEntry[prop].push(...(childRoleEntry[prop] || [] ));
                        } else {
                            let childFact = parseFloat(childRoleEntry[prop]) || 0;
                            if (childFact) {
                                parentRoleEntry[prop] = (parseFloat(parentRoleEntry[prop]) || 0) + childFact;
                            }
                        }
                    }
                }
            });
        }
    });
}

